#[no_mangle]
pub unsafe extern "C" fn set_pt_large_page(
    pt: *mut c_void,
    virt: *mut c_void,
    phys: CULong,
    attr: CULong,
) -> CInt {
    unsafe {
        x86_pt_set_page_bridge(
            pt,
            virt as CULong,
            phys,
            attr | PTATTR_LARGEPAGE | PTATTR_ACTIVE,
        )
    }
}
